mapper.insert:
INSERT INTO case_execution_log (plan_id, project_id, case_id, result, exec_type, execute_time, exec_date)
SELECT pc.plan_id, vp.project_id, pc.case_id, pc.result, #{execType}, #{executeTime}, #{execDate}
FROM plan_case pc
JOIN version_plan vp ON vp.id = pc.plan_id
WHERE pc.plan_id = #{planId}
  AND pc.result IN ('成功', '失败')

mapper.update:
UPDATE case_execution_log
SET execute_time = #{executeTime},
    exec_date = #{execDate}
WHERE plan_id = #{planId}
